{"cards": [{"node_code": "N_7fd4c3ecb62a82c4", "definition": "研究稳态电流产生的磁场分布、磁介质磁化特性及磁路计算的理论与方法，涵盖安培环路定理、毕奥-萨伐尔定律及磁位函数分析。", "boundary": "本节点聚焦于不含时间变化项的磁场理论，即恒定电流与静止磁体产生的场。包括磁介质中的本构关系、磁化强度、磁导率及等效磁路模型。若涉及时变磁场、电磁感应或电磁波传播，归入兄弟节点；若涉及具体电机磁路设计，归入电机节点。", "includes": ["恒定电流磁场分布与安培环路定理应用", "磁介质磁化机理、磁导率及磁路计算", "磁矢位与磁标位的数学描述及边界条件"], "excludes": ["时变磁场、电磁感应及电磁波传播理论", "电机、变压器等磁性机械的具体结构设计"], "sibling_distinctions": [{"other_code": "N_cb2f2908adaa969c", "rule": "本节点处理稳态磁场（无时间变化）；兄弟节点处理时变场、电磁感应及麦克斯韦方程组完整体系。"}, {"other_code": "N_33edc56f5ee61c70", "rule": "本节点研究静态或准静态磁场；兄弟节点研究高频时变电磁波的传播、辐射及屏蔽。"}], "cross_boundary_rule": "若内容涉及磁路计算但重点在于材料磁化特性或稳态场分布归入本节点；若重点在于时变感应效应归入法拉第电磁感应节点。"}, {"node_code": "N_cb2f2908adaa969c", "definition": "研究电磁感应定律、位移电流假说及麦克斯韦方程组的理论体系，涵盖感生/动生电动势、波动方程推导及电磁场能量传输机制。", "boundary": "本节点聚焦于时变电磁场的核心物理定律及其数学表达，包括法拉第定律、安培-麦克斯韦定律、高斯定律及坡印廷矢量。若涉及具体电磁波在介质中的传播特性归入平面电磁波节点；若涉及数值求解归入计算电磁学。", "includes": ["法拉第电磁感应定律及感生/动生电动势", "位移电流概念与完整麦克斯韦方程组推导", "电磁波动方程、能量密度及坡印廷矢量"], "excludes": ["电磁波在特定介质中的传播、反射与辐射细节", "电磁场问题的数值算法与仿真实现"], "sibling_distinctions": [{"other_code": "N_7fd4c3ecb62a82c4", "rule": "本节点处理时变场及电磁感应；兄弟节点处理稳态磁场及磁介质特性。"}, {"other_code": "N_33edc56f5ee61c70", "rule": "本节点侧重电磁场基本定律与能量守恒；兄弟节点侧重电磁波的具体传播模式、辐射源及屏蔽原理。"}], "cross_boundary_rule": "若内容涉及电磁波方程推导归入本节点；若涉及波在界面处的行为或具体辐射源归入平面电磁波节点。"}, {"node_code": "N_33edc56f5ee61c70", "definition": "研究平面电磁波在理想介质与导体中的传播特性、界面反射折射、基本辐射源模型及趋肤效应与电磁屏蔽原理。", "boundary": "本节点聚焦于时变电磁场的传播与辐射应用，包括波阻抗、极化、反射系数、赫兹偶极子辐射及导体中的趋肤深度。若涉及复杂几何下的数值仿真归入计算电磁学；若涉及电磁干扰防护工程归入电磁兼容。", "includes": ["平面波在介质/导体中的传播、极化与波阻抗", "电磁波在界面上的反射、折射与透射", "赫兹偶极子辐射、滞后位及趋肤效应原理"], "excludes": ["电磁场基本定律的推导（如麦克斯韦方程组）", "电磁兼容工程措施及生物电磁效应评估"], "sibling_distinctions": [{"other_code": "N_cb2f2908adaa969c", "rule": "本节点侧重电磁波传播与辐射的具体物理过程；兄弟节点侧重产生这些波的电磁感应定律与能量守恒基础。"}, {"other_code": "N_7fd4c3ecb62a82c4", "rule": "本节点处理高频时变电磁波；兄弟节点处理低频或稳态磁场。"}], "cross_boundary_rule": "若内容涉及电磁波传播的物理机制归入本节点；若涉及利用电磁波进行通信或雷达系统设计归入相应应用节点；若涉及抑制干扰归入电磁兼容。"}]}
